import type { Board, BoardItem, BoardItemStatus, Category, CategoryId, Phase, TimeSpan } from '../../domain/types'

/*
 * Mock category boards that rebuild specs/mockups/board-productivity-v1.png,
 * board-self-care-v1.png, and board-leisure-and-footer-v1.png.
 *
 * Every item is its own entity even when titles repeat ("Clean your room" is
 * placeholder copy). "See all" counts are real: a group showing "See all 22"
 * has 22 items in that area, generated by `repeatItems` below.
 */

export const MOCK_CATEGORIES: Record<CategoryId, Category> = {
  productivity: { id: 'productivity', name: 'Productivity', theme: 'productivity' },
  'self-care': { id: 'self-care', name: 'Self-Care', theme: 'self-care' },
  leisure: { id: 'leisure', name: 'Leisure', theme: 'leisure' },
  social: { id: 'social', name: 'Social', theme: 'self-care' },
}

/* ---------- Item builders ---------- */

const day = (n: number, hour = 0) => new Date(Date.UTC(2026, 10, 2 + n, hour)).toISOString()

/** Contiguous phases splitting `span` at the given fractions, like the mockup's strips. */
function splitPhases(prefix: string, span: TimeSpan, cuts: number[]): Phase[] {
  const start = Date.parse(span.start)
  const length = Date.parse(span.end) - start
  const at = (fr: number) => new Date(start + fr * length).toISOString()
  const edges = [0, ...cuts, 1]
  return edges.slice(0, -1).map((fr, i) => ({
    id: `${prefix}-phase-${i + 1}`,
    title: `Phase ${i + 1}`,
    start: at(fr),
    end: at(edges[i + 1]),
  }))
}

const WEEKLY_FS_SPAN: TimeSpan = { start: day(0), end: day(7) }
const F101_SPAN: TimeSpan = { start: day(0, 9), end: day(6, 17) }

function plain(id: string, title: string, categoryIds: CategoryId[], status: BoardItemStatus = 'todo'): BoardItem {
  return { id, title, status, categoryIds }
}

function weeklyFs(id: string, categoryIds: CategoryId[]): BoardItem {
  return {
    ...plain(id, 'Weekly FS Project', categoryIds),
    span: WEEKLY_FS_SPAN,
    phases: splitPhases(id, WEEKLY_FS_SPAN, [0.37, 0.6, 0.82]),
  }
}

function f101(id: string, categoryIds: CategoryId[]): BoardItem {
  return {
    ...plain(id, 'F101 Assignment', categoryIds),
    span: F101_SPAN,
    phases: splitPhases(id, F101_SPAN, [0.15, 0.55, 0.85]),
  }
}

/** `count` separate "Clean your room"-style filler items, ids `${prefix}-1`, `${prefix}-2`, … */
function repeatItems(
  prefix: string,
  count: number,
  categoryIds: CategoryId[],
  status: BoardItemStatus = 'todo',
  title = 'Clean your room',
): BoardItem[] {
  return Array.from({ length: count }, (_, i) => plain(`${prefix}-${i + 1}`, title, categoryIds, status))
}

/* ---------- Boards ---------- */

const items: BoardItem[] = []
const add = (...list: BoardItem[]) => {
  items.push(...list)
  return list.map((i) => i.id)
}

/**
 * The compact "routine" group shared by Self-Care and Leisure, and by
 * Productivity's low day: [Weekly FS, Clean your room, F101, +19] primary and
 * [Call Plumber (done), Meet Design Group, +132] in the Social lane.
 */
function routineItems(prefix: string, cat: CategoryId): string[] {
  const both = [cat, 'social']
  return [
    ...add(weeklyFs(`${prefix}-weekly-fs`, [cat]), plain(`${prefix}-clean`, 'Clean your room', [cat]), f101(`${prefix}-f101`, [cat])),
    ...add(...repeatItems(`${prefix}-more`, 19, [cat])),
    ...add({ ...plain(`${prefix}-call-plumber`, 'Call Plumber', both), status: 'done' }),
    ...add(plain(`${prefix}-meet-design`, 'Meet Design Group', both)),
    ...add(...repeatItems(`${prefix}-social`, 132, both)),
  ]
}

/**
 * The expanded "Unsorted" backlog: 9 primary, 6 Social, as drawn in the mockups
 * (09a says 10 primary, but the mockups show 9 and expanded groups show everything).
 */
function unsortedItems(prefix: string, cat: CategoryId, socialStatus: BoardItemStatus): string[] {
  const both = [cat, 'social']
  return [
    ...add(weeklyFs(`${prefix}-weekly-fs`, [cat]), plain(`${prefix}-clean`, 'Clean your room', [cat]), f101(`${prefix}-f101`, [cat])),
    ...add(...repeatItems(`${prefix}-more`, 6, [cat])),
    ...add({ ...plain(`${prefix}-call-plumber`, 'Call Plumber', both), status: 'done' }),
    ...add(plain(`${prefix}-meet-design`, 'Meet Design Group', both, socialStatus)),
    ...add(...repeatItems(`${prefix}-social`, 4, both, socialStatus)),
  ]
}

function wednesdayItems(prefix: string, cat: CategoryId): string[] {
  const both = [cat, 'social']
  return [
    ...add(f101(`${prefix}-f101`, [cat]), ...repeatItems(`${prefix}-more`, 21, [cat])),
    ...add(plain(`${prefix}-meet-design`, 'Meet Design Group', both), ...repeatItems(`${prefix}-social`, 21, both)),
  ]
}

